from dataclasses import dataclass
@dataclass
class MyState(StateSchema):
    completed: int = 0
state = MyState(task="Index notes", max_steps=3)

result = session.run()
print(result.state.final_result, result.state.stop_reason)
for record in result.records:
    for tool_result in record.action_results:
        print(tool_result.tool_name, tool_result.status)

@function_tool(read_only=True, concurrency_safe=True)
def title(text: str) -> str:
    return text.split(":", 1)[0]

# Class tools implement execute, not the compatibility run method.
class EchoTool(BaseTool):
    name = "echo"
    description = "Return a trusted input"
    def execute(self, args, runtime_context=None):
        return ToolResult(output=args)

class AuditedSelector(PriorityContextSelectionPolicy):
    def select(self, contributions, **options):
        contributions = tuple(contributions)
        print([item.contribution_id for item in contributions])
        return super().select(contributions, **options)

class PauseFirstTool(LifecyclePolicy):
    policy_id = "notes.pause"
    def should_pause(self, context):
        return context.step_id == 0

